macro_rules! deps {
    () => {
        StrRead!();
        SliceRead!();
        StreamDeserializer!();
        Position!();
        Reference!();
        Value!();
        Result!();
        RawValue!();
        IoRead!();
    };
}

macro_rules! Read {
    () => {
        deps!();
        # [doc = " Trait used by the deserializer for iterating over input. This is manually"] # [doc = " \"specialized\" for iterating over `&[u8]`. Once feature(specialization) is"] # [doc = " stable we can use actual specialization."] # [doc = ""] # [doc = " This trait is sealed and cannot be implemented for types outside of"] # [doc = " `serde_json`."] pub trait Read < 'de > : private :: Sealed { # [doc (hidden)] fn next (& mut self) -> Result < Option < u8 > > ; # [doc (hidden)] fn peek (& mut self) -> Result < Option < u8 > > ; # [doc = " Only valid after a call to peek(). Discards the peeked byte."] # [doc (hidden)] fn discard (& mut self) ; # [doc = " Position of the most recent call to next()."] # [doc = ""] # [doc = " The most recent call was probably next() and not peek(), but this method"] # [doc = " should try to return a sensible result if the most recent call was"] # [doc = " actually peek() because we don't always know."] # [doc = ""] # [doc = " Only called in case of an error, so performance is not important."] # [doc (hidden)] fn position (& self) -> Position ; # [doc = " Position of the most recent call to peek()."] # [doc = ""] # [doc = " The most recent call was probably peek() and not next(), but this method"] # [doc = " should try to return a sensible result if the most recent call was"] # [doc = " actually next() because we don't always know."] # [doc = ""] # [doc = " Only called in case of an error, so performance is not important."] # [doc (hidden)] fn peek_position (& self) -> Position ; # [doc = " Offset from the beginning of the input to the next byte that would be"] # [doc = " returned by next() or peek()."] # [doc (hidden)] fn byte_offset (& self) -> usize ; # [doc = " Assumes the previous byte was a quotation mark. Parses a JSON-escaped"] # [doc = " string until the next quotation mark using the given scratch space if"] # [doc = " necessary. The scratch space is initially empty."] # [doc (hidden)] fn parse_str < 's > (& 's mut self , scratch : & 's mut Vec < u8 >) -> Result < Reference < 'de , 's , str > > ; # [doc = " Assumes the previous byte was a quotation mark. Parses a JSON-escaped"] # [doc = " string until the next quotation mark using the given scratch space if"] # [doc = " necessary. The scratch space is initially empty."] # [doc = ""] # [doc = " This function returns the raw bytes in the string with escape sequences"] # [doc = " expanded but without performing unicode validation."] # [doc (hidden)] fn parse_str_raw < 's > (& 's mut self , scratch : & 's mut Vec < u8 > ,) -> Result < Reference < 'de , 's , [u8] > > ; # [doc = " Assumes the previous byte was a quotation mark. Parses a JSON-escaped"] # [doc = " string until the next quotation mark but discards the data."] # [doc (hidden)] fn ignore_str (& mut self) -> Result < () > ; # [doc = " Assumes the previous byte was a hex escape sequence ('\\u') in a string."] # [doc = " Parses next hexadecimal sequence."] # [doc (hidden)] fn decode_hex_escape (& mut self) -> Result < u16 > ; # [doc = " Switch raw buffering mode on."] # [doc = ""] # [doc = " This is used when deserializing `RawValue`."] # [cfg (feature = "raw_value")] # [doc (hidden)] fn begin_raw_buffering (& mut self) ; # [doc = " Switch raw buffering mode off and provides the raw buffered data to the"] # [doc = " given visitor."] # [cfg (feature = "raw_value")] # [doc (hidden)] fn end_raw_buffering < V > (& mut self , visitor : V) -> Result < V :: Value > where V : Visitor < 'de > ; # [doc = " Whether StreamDeserializer::next needs to check the failed flag. True"] # [doc = " for IoRead, false for StrRead and SliceRead which can track failure by"] # [doc = " truncating their input slice to avoid the extra check on every next"] # [doc = " call."] # [doc (hidden)] const should_early_return_if_failed : bool ; # [doc = " Mark a persistent failure of StreamDeserializer, either by setting the"] # [doc = " flag or by truncating the input data."] # [doc (hidden)] fn set_failed (& mut self , failed : & mut bool) ; }
    };
}

Read!()